from fastapi.responses import HTMLResponse
from echomatrix.api import app

HTML = '''<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>EchoMatrix</title><style>body{margin:0;background:#071018;color:#eaf2f8;font:14px system-ui}header{padding:22px;border-bottom:1px solid #20303b}.wrap{max-width:1300px;margin:auto;padding:20px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card{background:#0d1821;border:1px solid #213541;border-radius:14px;padding:16px}.wide{grid-column:span 2}.big{font-size:27px;font-weight:800;margin:7px 0}.muted{color:#8ca0ad}.row{display:flex;justify-content:space-between;margin:8px 0}.btn{padding:9px;border:1px solid #315568;background:#10232e;color:white;border-radius:8px}.log{max-height:180px;overflow:auto}@media(max-width:800px){.grid{grid-template-columns:1fr 1fr}.wide{grid-column:span 2}}@media(max-width:520px){.grid{grid-template-columns:1fr}.wide{grid-column:span 1}}</style></head><body><header><b style="font-size:24px">◈ EchoMatrix</b><div class="muted">AI-native market intelligence · strategy research · simulation</div></header><main class="wrap"><div class="grid"><div class="card"><div class="muted">MARKET REGIME</div><div id="regime" class="big">—</div><div id="opp" class="muted">—</div></div><div class="card"><div class="muted">SIMULATOR EQUITY</div><div id="eq" class="big">—</div><div id="bal" class="muted">—</div></div><div class="card"><div class="muted">RISK GOVERNOR</div><div id="risk" class="big">—</div><div id="rm" class="muted">—</div></div><div class="card"><div class="muted">AI PROVIDERS</div><div class="row">Gemini <b id="gem">—</b></div><div class="row">Groq <b id="groq">—</b></div></div><div class="card wide"><h3>World Model</h3><div id="world"></div></div><div class="card wide"><h3>Model Council · Evidence Fusion</h3><div id="models"></div></div><div class="card"><h3>Simulator</h3><button class="btn" onclick="openP()">Open virtual position</button> <button class="btn" onclick="step()">Market step</button><div id="pos" class="log"></div></div><div class="card"><h3>Strategy Brain</h3><div id="strat" class="log"></div></div><div class="card"><h3>Memory</h3><div id="mem" class="log"></div></div><div class="card"><h3>System Pipeline</h3><div class="muted">Data → World Model → Model Council → Evidence Fusion → Strategy Brain → Risk Governor → Simulation → Outcome → Memory</div></div></div></main><script>const q=s=>document.querySelector(s);async function api(u,o){return (await fetch(u,o)).json()}async function refresh(){let d=await api('/api/dashboard'),w=d.world;q('#regime').textContent=w.regime;q('#opp').textContent='Opportunity '+w.models.opportunity_score+' · uncertainty '+w.models.uncertainty;q('#eq').textContent='$'+d.equity.toFixed(2);q('#bal').textContent='Balance $'+d.balance.toFixed(2);q('#risk').textContent=d.risk.state;q('#rm').textContent='Open '+d.risk.open_positions+' / '+d.risk.max_open_positions;q('#gem').textContent=d.providers.gemini?'READY':'CONFIGURE';q('#groq').textContent=d.providers.groq?'READY':'CONFIGURE';q('#world').innerHTML=['price','ema_fast','ema_slow','momentum','volatility'].map(k=>'<div class="row"><span>'+k+'</span><b>'+w[k]+'</b></div>').join('');q('#models').innerHTML=Object.entries(w.models).map(x=>'<div class="row"><span>'+x[0]+'</span><b>'+x[1]+'</b></div>').join('');q('#pos').innerHTML=d.positions.length?d.positions.map(p=>'<div class="row"><span>'+p.symbol+' '+p.side+'</span><b>'+p.pnl.toFixed(2)+' <button class="btn" onclick="closeP(\\''+p.id+'\\')">Close</button></b></div>').join(''):'No open virtual positions';q('#strat').innerHTML=d.strategies.map(s=>'<div class="row"><span>'+s.name+'</span><b>'+s.status+' · '+s.score+'</b></div>').join('');q('#mem').innerHTML=d.memory.length?d.memory.map(m=>'<div>'+m.lesson+' · '+m.pnl+'</div>').join(''):'No recorded outcomes yet'}async function openP(){await api('/api/simulator/open',{method:'POST',headers:{'content-type':'application/json'},body:'{}'});refresh()}async function step(){await api('/api/simulator/step',{method:'POST'});refresh()}async function closeP(id){await api('/api/simulator/close/'+id,{method:'POST'});refresh()}refresh();setInterval(refresh,3000)</script></body></html>'''

@app.get('/', response_class=HTMLResponse)
def home():
    return HTML
